(function(api){
var clouds=[], spr=null;
function mkSpr(){
  var s=api.canvas.ownerDocument.createElement('canvas');
  s.width=160; s.height=160;
  var c=s.getContext('2d');
  var g=c.createRadialGradient(80,80,10,80,80,80);
  g.addColorStop(0,'rgba(80,80,88,0.55)');
  g.addColorStop(0.6,'rgba(80,80,88,0.22)');
  g.addColorStop(1,'rgba(80,80,88,0)');
  c.fillStyle=g; c.fillRect(0,0,160,160);
  return s;
}
function num(k,d){ var p=api.params||{}; return p[k]!=null?+p[k]:d; }
function frame(dt){
  var W=api.width,H=api.height; if(!W||!H) return;
  var f=dt/16.6;
  if(!spr) spr=mkSpr();
  var n=Math.max(0,num('amount',5)), spd=Math.max(0.2,num('speed',3))*0.08, dim=num('dim',2);
  var ctx=api.ctx;
  ctx.clearRect(0,0,W,H);
  while(clouds.length<n*3){
    clouds.push({x:api.rand(-300,W+100), y:api.rand(-40,H*0.55), r:api.rand(90,240), a:api.rand(0.25,0.6), v:api.rand(0.5,1.4)});
  }
  if(clouds.length>n*3) clouds.length=n*3;
  for(var i=0;i<clouds.length;i++){
    var c=clouds[i];
    c.x+=c.v*spd*f;
    if(c.x-c.r>W+200){ c.x=-c.r-50; c.y=api.rand(-40,H*0.55); }
    ctx.globalAlpha=c.a;
    var d2=c.r*2;
    ctx.drawImage(spr,c.x-c.r,c.y-c.r*0.55,d2,d2*0.55);
  }
  ctx.globalAlpha=1;
  if(dim>0){ ctx.fillStyle='rgba(60,60,66,'+(0.04*dim)+')'; ctx.fillRect(0,0,W,H); }
}
function clear(){ try{ api.ctx.clearRect(0,0,api.width,api.height); }catch(e){} clouds=[]; }
return { frame:frame, clear:clear, resize:clear };
})
